[x, fval] = paretosearch(fun, 2, A, b, [], [], lb, []);
% 输出部分 Pareto 解
for i = 1:min(5, size(x, 1))
    fprintf('解 %d: x1 = %.2f, x2 = %.2f, 利润 = %.2f, 成本 = %.2f\n', i, x(i,1), x(i,2), -fval(i,1), fval(i,2));
